head.script:
// 테스트 설명, 유효성 값 설정
//  - description 은 @description 첫 문장만.
//  - @description 의 | 추가문(accessibility=true 면 senseReader 무관 scrollFocus 항상 true) 은 validation 으로 분리.
scwin.tData = {
    "description" : "[gridView > P > scrollFocus]<br/>senseReader=true 일때 세로 스크롤 영역으로 키보드에 의한 포커스 이동을 허용할지 설정합니다.",
    "validation" : [
        "accessibility=true 이면 senseReader 속성값에 관계없이 scrollFocus 속성은 항상 true 로 동작합니다.",
        "true 설정 시, 키보드에 의한 포커스 이동 시 세로 스크롤 영역으로 포커스를 이동할 수 있습니다.",
        "true 설정 시, GridView 의 마지막 Body Cell 이 포커스된 상태에서 Tab 키 입력 시 세로 스크롤 영역으로 포커스가 이동합니다.",
        "false 설정 시, 키보드에 의한 포커스 이동 시 세로 스크롤 영역으로 포커스를 이동할 수 없습니다.",
        "미설정 시, 키보드에 의한 포커스 이동 시 세로 스크롤 영역으로 포커스를 이동할 수 없습니다.",
        "세로 스크롤이 표시되지 않는 경우 적용되지 않습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출 (gdl_boolean 등)
    $c.gcm.createCommonDatalist();

    // 정적 select1(gdl_boolean)은 초기 selectedIndex 미적용 -> 기본값 명시 설정 (코드값 미설정="1"/true="2"/false="3")
    //  scrollFocus 기본값 false -> 코드 "3". accessibility 는 전제(senseReader=true) 경로를 쓰도록 미설정("1") 시작.
    con_scrollFocus.setValue("3");
    con_accessibility.setValue("1");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  scrollFocus / senseReader / accessibility 는 렌더 시 결정되는 속성이므로
//  con 변경 후 "Target 재생성"(btn_createTarget -> comp_init) 으로만 반영한다.
//  - 전제: senseReader=true + 세로 스크롤 표시(데이터 20행 / visibleRowNum=5 로 고정 높이 -> 세로 스크롤 발생)
//  - useStartEndDiv=false 로 시작/끝 div 포커스 트랩을 제거해 scrollFocus 동작만 격리 검증
//  - 검증 신호: 세로 스크롤 영역(scrollY_div) 의 tabIndex 부여 여부.
//      scrollFocus=true(또는 accessibility=true) -> tabIndex=0(마지막 셀 Tab 이 스크롤 영역으로 이동하는 의도된 탭 정지점)
//      scrollFocus=false/미설정               -> tabIndex 미부여(엔진상 탭 정지점 아님)
//    (nextTabID 를 설정하면 엔진이 마지막 셀 Tab 시 스크롤 영역을 건너뛰고 nextTabID 로 바로 이동하므로 사용하지 않음)
//  - [MCP 실측 주의] Chrome 등 최신 브라우저(Chrome 125+ keyboard-focusable scrollers)는 스크롤 가능한 div 를
//    tabIndex 없이도 native 로 포커스 대상에 포함한다. 따라서 scrollFocus=false 여도 마지막 셀 Tab 시
//    scrollY_div 로 focus 가 갈 수 있으나 이는 브라우저 native 동작이며, 엔진의 scrollFocus 적용 여부와는 별개다.
//    scrollFocus 적용의 결정적 신호는 scrollY_div 의 tabIndex(0=엔진이 부여한 탭 정지점) 이다.
//    (본 샘플의 onScrollYFocus 는 focus 시 tabIndex 를 함께 출력해 true=적용 / false=미적용 을 구분한다.)
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // con 선택값 (gdl_boolean 바인딩 -> getText() 로 라벨(''/'true'/'false') 분기)
    let vScrollFocus   = con_scrollFocus.getText();
    let vAccessibility = con_accessibility.getText();

    // 테스트 참고 라벨 (가장 먼저 생성)
    let lblDesc = '[전제] senseReader=true 고정(accessibility=true 선택 시 엔진이 senseReader/scrollFocus 강제 true). 데이터 20행 + visibleRowNum=5(고정 높이) -> 세로 스크롤 표시. useStartEndDiv=false(시작/끝 div 포커스 트랩 제거).'
        + '\n[절차] (a)con_scrollFocus(true/false/미설정) 또는 con_accessibility(true) 선택 -> Target 재생성.'
        + '\n       (b)그리드 마지막 Body Cell(col4 마지막 행) 을 클릭해 포커스한 뒤 Tab 키 입력.'
        + '\n[확인] (1)scrollFocus=true 또는 accessibility=true -> 세로 스크롤 영역(scrollY_div) 에 tabIndex=0 부여 -> 마지막 셀 Tab 시 스크롤 영역으로 포커스 이동(하단에 tabIndex=0 -> 적용 메시지 출력).'
        + '\n       (2)scrollFocus=false/미설정 -> 세로 스크롤 영역에 tabIndex 미부여(엔진상 탭 정지점 아님) -> 마지막 셀 Tab 시 tabIndex=null -> 미적용 메시지 출력.'
        + '\n       (주의) 최신 브라우저(Chrome 125+)는 스크롤 div 를 native 로 포커스하므로 false 여도 focus 자체는 scrollY_div 로 갈 수 있음. 적용 여부는 tabIndex(0=엔진 탭 정지점)로 판정.'
        + '\n       (3)[상태확인] 버튼: scrollFocus 적용값 / 세로 스크롤 표시여부 / 세로 스크롤 영역 tabIndex(0=적용, 그 외=미적용) 확인. 세로 스크롤 미표시 시 tabIndex=-1(적용 안 됨).';
    $c.gcm.createLabel('label="' + lblDesc + '"', '', 'label1');

    // 세로 스크롤 발생을 위해 20행 데이터리스트 인라인 생성 (공통 헬퍼는 4행이라 부족)
    let ns = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + ns + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    scwin.fillData();

    // 조건 설정
    let properties = {
        focusMode    : "cell",
        visibleRowNum: "5",       // 고정 높이(5행) -> 20행 데이터로 세로 스크롤 발생
        useStartEndDiv: "false"   // 시작/끝 div 포커스 트랩 제거
    };
    if (vAccessibility === 'true') {
        // accessibility=true -> 엔진이 senseReader/scrollFocus 를 강제 true (scrollFocus con 값 무관)
        properties.accessibility = "true";
    } else {
        // 전제조건 senseReader=true 고정
        properties.senseReader = "true";
        // scrollFocus : '' 미설정 시 속성 제외(엔진 기본 false)
        if (vScrollFocus === 'true') {
            properties.scrollFocus = "true";
        } else if (vScrollFocus === 'false') {
            properties.scrollFocus = "false";
        }
    }

    let cList = $c.gcm.createCList(properties);

    // target 생성 (4컬럼 Body 그리드)
    await scwin.createGridView(cList);

    // 세로 스크롤 영역(scrollY_div) 에 focus 리스너 부착 -> 실제 Tab 으로 포커스가 이동하면 tabIndex 와 함께 메시지 출력
    let scrollYDiv = document.getElementById('mf_target1_scrollY_div');
    if (scrollYDiv) {
        scrollYDiv.addEventListener('focus', scwin.onScrollYFocus);
    }

    // 마지막 Body Cell(마지막 행, col4) 에 포커스 -> 사용자는 이 셀에서 Tab 만 누르면 됨
    let lastRow = dlt_bind.getRowCount() - 1;
    target1.setFocusedCell(lastRow, 3, true);
}



// 세로 스크롤 발생용 데이터 (20행)
scwin.fillData = function () {
    let rows = [];
    for (let i = 1; i <= 20; i++) {
        rows.push({ col1: "A" + i, col2: "B" + i, col3: "C" + i, col4: "D" + i });
    }
    dlt_bind.setJSON(rows, false);
}



// gridView 동적 생성 (4컬럼)
scwin.createGridView = async function (cList) {
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' checkAllType="false" id="" dataList="data:dlt_bind" style="width:420px;height:150px;">';
    s += '<w2:caption style="" id="caption1" value="scrollFocus 테스트 그리드 (세로 스크롤 표시)"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="100" style="" inputType="text" id="column1" value="col1"></w2:column>';
    s += '<w2:column width="100" style="" inputType="text" id="column2" value="col2"></w2:column>';
    s += '<w2:column width="100" style="" inputType="text" id="column3" value="col3"></w2:column>';
    s += '<w2:column width="100" style="" inputType="text" id="column4" value="col4(마지막)"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="100" style="" inputType="text" id="col1" dataList="col1"></w2:column>';
    s += '<w2:column width="100" style="" inputType="text" id="col2" dataList="col2"></w2:column>';
    s += '<w2:column width="100" style="" inputType="text" id="col3" dataList="col3"></w2:column>';
    s += '<w2:column width="100" style="" inputType="text" id="col4" dataList="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// (검증) @propval true / accessibility 강제 : 마지막 Body Cell 에서 Tab 시 세로 스크롤 영역으로 포커스 이동
//  scrollY_div 가 실제 focus 를 받으면 발화 -> 사용자 조작(Tab) 기반으로 입증.
//  scrollY_div 의 tabIndex 를 함께 출력해 scrollFocus 적용(=0) 여부를 명시한다.
scwin.onScrollYFocus = function () {
    let sy = document.getElementById('mf_target1_scrollY_div');
    let ti = sy ? sy.getAttribute('tabIndex') : null;
    wf_body_bottom.getObj("scwin").setReturnValue(
        "세로 스크롤 영역(scrollY_div) 으로 포커스 이동됨 (마지막 Body Cell Tab) | tabIndex=" + ti
        + " -> " + (ti === '0' ? 'scrollFocus 적용(의도된 탭 정지점)' : 'scrollFocus 미적용(tabIndex 미부여)'));
}



// (검증) 상태 확인 : scrollFocus 적용값 / senseReader / 세로 스크롤 표시여부 / scrollY_div tabIndex
//  @spec : 세로 스크롤이 표시되지 않으면 tabIndex 가 -1 로 유지되어 적용되지 않음 (tabIndex 0 = 이동 가능)
scwin.btn_checkState_onclick = function () {
    let sy = document.getElementById('mf_target1_scrollY_div');
    let hasVScroll = sy ? (sy.offsetHeight < sy.scrollHeight) : false;
    wf_body_bottom.getObj("scwin").setReturnValue(
        "[scrollFocus 적용값] " + target1.options.scrollFocus
        + " | [senseReader] " + target1.options.senseReader
        + " | [세로 스크롤 표시] " + hasVScroll
        + " | [세로 스크롤 영역 tabIndex] " + (sy ? sy.getAttribute('tabIndex') : 'N/A'));
}
